import 'server-only'
import type { StoreDeSessao, SessaoArmazenada } from '../portas/sessao.js'
export async function sessaoAssincrona(): Promise<StoreDeSessao> {
  const m = new Map<string, SessaoArmazenada>()
  return { async ler(id) { return m.get(id) ?? null }, async gravar(id, s) { m.set(id, s) }, async remover(id) { m.delete(id) } } as StoreDeSessao
}

