import 'server-only'
import type { StoreDeSessao, LeitorDeSessao, SessaoArmazenada } from '../portas/sessao.js'
export function sessaoFlexivel(escrita: boolean): LeitorDeSessao | StoreDeSessao {
  const m = new Map<string, SessaoArmazenada>()
  const l: LeitorDeSessao = { async ler(id) { return m.get(id) ?? null } } as LeitorDeSessao
  return escrita ? ({ ...l, async gravar(id: string, s: SessaoArmazenada) { m.set(id, s) }, async remover(id: string) { m.delete(id) } } as StoreDeSessao) : l
}

